import React, { useState, useEffect } from 'react';
import Home from './pages/Home';
import Game from './pages/Game';
import About from './pages/About';
import Settings from './pages/Settings';
import Layout from './components/Layout';
import './styles/globals.css';

function App() {
  const [view, setView] = useState('home');
  const [gameMode, setGameMode] = useState(null);

  // Inicializar definições do LocalStorage ou usar default
  const [settings, setSettings] = useState(() => {
    const saved = localStorage.getItem('raw_settings');
    return saved ? JSON.parse(saved) : {
      animations: true,
      explicit: true,
      language: 'PT-PT'
    };
  });

  // Salvar sempre que mudarem
  useEffect(() => {
    localStorage.setItem('raw_settings', JSON.stringify(settings));
  }, [settings]);

  const handleStartGame = (modeId) => {
    setGameMode(modeId);
    setView('game');
  };

  const handleUpdateSetting = (key, value) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  return (
    <Layout onOpenSettings={() => setView('settings')} currentLang={settings.language}>
      {view === 'home' && (
        <div className={settings.animations ? "animate-in fade-in duration-500" : ""}>
          <Home onNavigate={handleStartGame} />
        </div>
      )}
      
      {view === 'game' && (
        <div className={settings.animations ? "animate-in slide-in-from-right duration-500" : ""}>
          <Game modeId={gameMode} onBack={() => setView('home')} settings={settings} />
        </div>
      )}

      {view === 'about' && (
        <div className={settings.animations ? "animate-in slide-in-from-bottom duration-500" : ""}>
          <About onBack={() => setView('home')} />
        </div>
      )}

      {view === 'settings' && (
        <div className={settings.animations ? "animate-in slide-in-from-top duration-500" : ""}>
          <Settings 
            settings={settings} 
            onUpdate={handleUpdateSetting} 
            onBack={() => setView('home')} 
          />
        </div>
      )}

      {/* Navegação Rápida Lateral */}
      {view === 'home' && (
        <>
          <button 
            onClick={() => setView('about')}
            className="fixed bottom-8 left-8 text-[10px] text-raw-bone/40 hover:text-raw-cyan uppercase tracking-widest font-bold rotate-90 origin-left z-50 transition-colors"
          >
            Story
          </button>
          <button 
            onClick={() => setView('settings')}
            className="fixed top-24 right-8 text-[10px] text-raw-bone/40 hover:text-raw-cyan uppercase tracking-widest font-bold -rotate-90 origin-right z-50 transition-colors"
          >
            Config
          </button>
        </>
      )}
    </Layout>
  );
}

export default App;
